<div class="d-flex justify-content-between mb-3"><h2 class="fw-bold">Notifications</h2><form method="post" action="<?=e(base_url('notifications/read-all'))?>"><?=csrf_field()?><button class="btn btn-outline-dark">Tout marquer comme lu</button></form></div><div class="km-card p-3"><?php if(!$notifications):?><p class="text-muted">Aucune notification.</p><?php endif;?><?php foreach($notifications as $n):?><div class="d-flex justify-content-between align-items-start border-bottom py-3 <?=!$n['is_read']?'fw-semibold':''?>"><div><div><?=e($n['title'])?></div><div class="small text-muted"><?=e($n['message'])?> · <?=e($n['created_at'])?></div></div><?php if(!$n['is_read']):?><form method="post" action="<?=e(base_url('notifications/'.$n['id'].'/read'))?>"><?=csrf_field()?><button class="btn btn-sm btn-outline-dark">Lu</button></form><?php endif;?></div><?php endforeach;?></div>
